int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    int ret = -EINVAL;
    struct socket *new_sk = NULL;

    if (!sk || !sockp)
        return -EINVAL;

    if (id <= 0)
        return -EINVAL;

    /* Check if the association exists and is valid. */
    if (!sctp_id2assoc(sk, id))
        return -ENOENT;

    /* Ensure no threads are waiting for buffer space on the association. */
    if (sctp_has_pending_buffers(sk, id)) {
        return -EBUSY;
    }

    /* Create a new socket. */
    ret = sock_create_kern(current->nsproxy->net_ns, PF_INET, sk->sk_type, sk->sk_protocol, &new_sk);
    if (ret < 0) {
        return ret;
    }

    /* Copy relevant properties from the original socket to the new one. */
    sctp_copy_properties(sk, new_sk->sk);

    /* Migrate the association to the new socket. */
    ret = sctp_migrate_assoc(sk, id, new_sk->sk);
    if (ret < 0) {
        sock_release(new_sk);
        return ret;
    }

    *sockp = new_sk;
    return 0;
}
